#!/usr/bin/env bun

import {spawnSync} from 'child_process';
import fs from 'fs';

// Linear issue prefix — override via ISSUE_PREFIX env var
const ISSUE_PREFIX = process.env.ISSUE_PREFIX || 'PRO';

const commitTypes = ['feat', 'fix', 'perf', 'chore', 'docs', 'refactor', 'security', 'style', 'test'];

// type: subject  OR  type!: subject  (breaking change)  OR  type: [PRO-123] subject
const commitMessageRegex = new RegExp(
  `^(${commitTypes.join('|')})!?: (\\[${ISSUE_PREFIX}-\\d+\\] )?.+$`
);

// git autogenerated commits — skip validation
const commitFixupRegex = /^(fixup|squash|amend)!/;
const mergeRegex = /^Merge /;

function printExamples(): void {
  console.log(`\nCommit message format:  type: [${ISSUE_PREFIX}-123] subject`);
  console.log(`${ISSUE_PREFIX} number is optional.`);
  console.log('\nValid types:', commitTypes.join(', '));
  console.log('\nExamples:');
  console.log(`  feat: [${ISSUE_PREFIX}-123] add user authentication`);
  console.log('  fix: handle null pointer in session cleanup');
  console.log(`  chore: [${ISSUE_PREFIX}-456] update dependencies`);
  console.log('  docs: update README with setup instructions');
  console.log('  refactor: extract auth logic into its own module');
  console.log('  test: add integration tests for login flow');
  console.log('\nBreaking changes — add ! after the type:');
  console.log(`  feat!: [${ISSUE_PREFIX}-111] drop support for Node 18\n`);
}

function validateCommitMessage(commitMessage: string): boolean {
  const firstLine = commitMessage?.split('\n')[0]?.trim();
  return commitMessageRegex.test(firstLine as string);
}

function getBranchName(): string {
  const result = spawnSync('git', ['rev-parse', '--abbrev-ref', 'HEAD']);
  return result.stdout.toString().trim();
}

function extractIssueId(branchName: string, commitMessage: string): string | null {
  // Try branch name first (e.g. PRO-123-add-feature or josh/PRO-456-fix)
  const prefixPattern = new RegExp(`${ISSUE_PREFIX}-\\d+`, 'i');
  const branchMatch = branchName.match(prefixPattern);
  if (branchMatch) {
    return branchMatch[0].toUpperCase();
  }

  // Then try existing commit message
  const commitMatch = commitMessage.match(new RegExp(`\\[${ISSUE_PREFIX}-\\d+\\]`, 'i'));
  if (commitMatch) {
    return commitMatch[0].replace(/[\[\]]/g, '').toUpperCase();
  }

  return null;
}

function insertIssueId(commitMessage: string, issueId: string): string {
  const lines = commitMessage.split('\n');
  const firstLine = lines[0] ?? '';

  if (firstLine.includes(`[${issueId}]`)) {
    return commitMessage;
  }

  const colonIdx = firstLine.indexOf(':');
  if (colonIdx === -1) {
    lines[0] = `[${issueId}] ${firstLine}`;
  } else {
    const type = firstLine.slice(0, colonIdx).trim();
    const rest = firstLine.slice(colonIdx + 1).trim();
    lines[0] = `${type}: [${issueId}] ${rest}`;
  }
  return lines.join('\n');
}

async function promptForCommitType(consoleIterator: AsyncIterableIterator<string>): Promise<string> {
  const promptMessage = `\nChoose a commit type:\n${commitTypes.map((type, i) => `  ${i + 1}) ${type}`).join('\n')}\nEnter number (or press ENTER for 'chore'): `;

  while (true) {
    process.stdout.write(promptMessage);
    const result = await consoleIterator.next();
    const line = result.value as string;
    if (!line) {
      return 'chore';
    }
    const index = parseInt(line.trim(), 10) - 1;
    if (index >= 0 && index < commitTypes.length) {
      return commitTypes[index] as string;
    }
    console.log('Invalid choice, please try again.');
  }
}

async function main() {
  try {
    const commitMessageFile = process.argv[2];
    if (!commitMessageFile) {
      printExamples();
      process.exit(1);
    }

    let commitMessage = fs.readFileSync(commitMessageFile, 'utf8');
    const firstLine = commitMessage.split('\n')[0]?.trim() ?? '';

    // Skip auto-generated commits
    if (commitFixupRegex.test(firstLine) || mergeRegex.test(firstLine)) {
      process.exit(0);
    }

    const branchName = getBranchName();

    if (!validateCommitMessage(commitMessage)) {
      console.log(`\nInvalid or missing commit type in: "${firstLine}"`);

      const consoleIterator = console[Symbol.asyncIterator]();
      const commitType = await promptForCommitType(consoleIterator);

      // Strip any existing type prefix so we don't double-apply
      const stripped = firstLine.replace(/^[\w-]+!?:\s*/, '');
      const subject = stripped || firstLine;

      const restLines = commitMessage.split('\n').slice(1).join('\n');
      commitMessage = `${commitType}: ${subject}${restLines ? '\n' + restLines : ''}`;
    }

    // Auto-insert issue ID from branch name if not already present
    const issueId = extractIssueId(branchName, commitMessage);
    if (issueId) {
      commitMessage = insertIssueId(commitMessage, issueId);
    }

    fs.writeFileSync(commitMessageFile, commitMessage);

    if (!validateCommitMessage(commitMessage)) {
      console.error('\nCommit message still invalid after correction. Please follow the format:');
      printExamples();
      process.exit(1);
    }

    console.log('Commit message is valid.');
    process.exit(0);
  } catch (error) {
    console.error('An error occurred:', error);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error('Error:', error);
  process.exit(1);
});
